            Memo8.Name = "Memo8";
            Memo8.Location = new System.Drawing.Point(16, 351);
            Memo8.Size = new System.Drawing.Size(665, 209);
            Memo8.TabIndex = 2;
            Memo8.BackColor = System.Drawing.Color.White;
            Memo8.Multiline = true;
            Memo8.Text = "\n\r   Untuk menggunakan metode ini, anda harus memiliki Rekening Akun sbb :\n\r\n\r   1. Rekening Akun Cadangan Resiko Pinjaman (CRP) di Group Aktiva.\n\r       Akun ini bisa anda buat sebagai salah satu Akun Detil pada Header Akun Pinjaman atau dibuat dengan Header tersendiri\n\r       Adapun Metode pencatatan CRP sbb :\n\r       - Pada saat terjadi pengakuan Biaya akibat peningkatan rasio kolektibilitas, maka pada akun ini dicatatkan transaksi Kredit (-)\n\r       - Pada saat terjadi pengakuan Pendapatan akibat berkurangnya rasio kolektibilitas, maka  pada akun ini dicatatkan transaksi Debet (+)\n\r   2. Rekening Akun Biaya Cadangan Resiko Pinjaman\n\r       Akun ini bisa anda buat sebagai Akun Detil pada Header Akun Biaya Penghapusan Piutang\n\r       Pada saat pencatatan Biaya CRP maka pada akun ini akan dicatatkan penambahan Saldo Debet (+)\n\r   3. Rekening Akun Pendapatan Lain-Lain\n\r       Akun ini bisa anda buat sebagai Akun Detil pada Header Akun Pendapatan Operasional\n\r       Pada saat pencatatan Pendapatan CRP maka pada akun ini akan dicatatkan penambahan Saldo Kredit (+)";
            Memo8.ReadOnly = true;
            Memo8.BorderStyle = System.Windows.Forms.BorderStyle.None;
