            // 
            // Memo7
            // 
            Memo7.Name = "Memo7";
            Memo7.Location = new System.Drawing.Point(16, 331);
            Memo7.Size = new System.Drawing.Size(665, 209);
            Memo7.TabIndex = 0;
            Memo7.Multiline = true;
            Memo7.Text = "\n\r   Untuk menggunakan metode ini, anda harus memiliki Rekening Akun sbb :\n\r\n\r   1. Rekening Akun Cadangan Resiko Pinjaman (CRP) di Group Pasiva.\n\r       Akun ini bisa anda buat sebagai salah satu Akun Detil pada Header Akun Modal atau dibuat dengan Header tersendiri\n\r       Adapun Metode pencatatan CRP sbb :\n\r       - Pada saat terjadi pengakuan Biaya akibat peningkatan rasio kolektibilitas, maka pada akun ini dicatatkan transaksi Kredit (+) \n\r         dan penambahan Saldo (+)\n\r       - Pada saat terjadi pengakuan Pendapatan akibat berkurangnya rasio kolektibilitas, maka  pada akun ini dicatatkan transaksi \n\r         Debet (+) dan pengurangan Saldo (-)\n\r   2. Rekening Akun Biaya Cadangan Resiko Pinjaman\n\r       Akun ini bisa anda buat sebagai Akun Detil pada Header Akun Biaya Penghapusan Piutang\n\r       Pada saat pencatatan Biaya CRP maka pada akun ini akan dicatatkan Debet (+) dan penambahan Saldo (+)\n\r   3. Rekening Akun Pendapatan Lain-Lain\n\r       Akun ini bisa anda buat sebagai Akun Detil pada Header Akun Pendapatan Operasional\n\r       Pada saat pencatatan Pendapatan CRP maka pada akun ini akan dicatatkan Kredit (+) dan penambahan Saldo (+)";
            Memo7.ReadOnly = true;
            Memo7.BorderStyle = System.Windows.Forms.BorderStyle.None;
